type Spec[T any] func(T) bool

func And[T any](specs ...Spec[T]) Spec[T] {
	return func(candidate T) bool {
		for _, s := range specs {
			if !s(candidate) { return false }
		}
		return true
	}
}

overdue := func(i Invoice) bool { return i.DaysPastDue >= 30 }
collectable := And[Invoice](overdue, func(i Invoice) bool { return !i.InCollection })
